### Issue description

It's impossible to build abstraction on top of repositories with generics 

### Expected Behavior

I want to build a custom abstract repo that will override each method. But I can't build it because of the definition of this type QueryDeepPartialEntity

```typescript
import { EntityHelper } from '@libs/core-modules/database/common/entity-helper';
import {
  Column,
  CreateDateColumn,
  DataSource,
  EntityTarget,
  InsertResult,
  Repository,
  UpdateDateColumn,
  VersionColumn,
} from 'typeorm';
import { QueryDeepPartialEntity } from 'typeorm/query-builder/QueryPartialEntity';

abstract class BaseEntityHelper extends EntityHelper {
  id!: string | number;

  @CreateDateColumn()
  createdAt!: Date;

  @UpdateDateColumn()
  updatedAt!: Date;

  @Column({ nullable: true, type: 'datetime' })
  deletedAt?: Date;

  @VersionColumn()
  version!: number;
}

export default abstract class BaseRepository<
  ENTITY extends BaseEntityHelper,
> extends Repository<ENTITY> {
  protected constructor(
    entityTarget: EntityTarget<ENTITY>,
    private dataSource: DataSource,
  ) {
    super(entityTarget, dataSource.createEntityManager());
  }

  insertOne(
    entity: QueryDeepPartialEntity<ENTITY>,
  ): Promise<InsertResult> {
    // error here, property doesn't exist
    // but it should be here because ENTITY must extend BaseEntityHelper
    console.log(entity.createdAt);

    return super.insert(entity);
  }
}

```




### Actual Behavior

Access obviously defined fields when using the inheritance model 

