Here's the naming strategy:
 ``` 
  import { DefaultNamingStrategy, NamingStrategyInterface } from "typeorm";

  export class SASNamingStrategy extends DefaultNamingStrategy implements NamingStrategyInterface{
	tableName(targetName: string, userSpecifiedName: string): string {
          return userSpecifiedName ? userSpecifiedName : snakeCase(targetName);
        }

        columnName(propertyName: string, customName: string, embeddedPrefixes: string[]): string {
            return snakeCase(embeddedPrefixes.concat(customName 
                 ? customName 
                 : propertyName).join("_"));
         }

         columnNameCustomized(customName: string): string {
             return customName;
         }

        relationName(propertyName: string): string {
            return snakeCase(propertyName);
	}	
  }

  function snakeCase(str: string) {
	return str.replace(/(?:([a-z])([A-Z]))|(?:((?!^)[A-Z])([a-z]))/g, "$1_$3$2$4").toLowerCase();
  }
```

